/// <summary>
///     The <c>AVAWHSZoneDbt_Extension</c> class is the extension for <c>WHSZone</c>
/// </summary>
[ExtensionOf(tableStr(WHSZone))]
final class AVAWHSZoneDbt_Extension
{
}

Method.Source:
 /// <summary>
 ///     AVA - Schneider 24.07.2024
 ///     AVA <c>avaWHSZoneGroupShipment</c> method.
 /// </summary>
 /// <returns>
 ///     <c>boolean</c> as type
 /// </returns>
 [SysClientCacheDataMethodAttribute(true)]
 display boolean avaWHSZoneGroupShipment()
 {
     boolean         retVal;

     WHSZoneGroup    locWHSZoneGroup;

     if(     this.ZoneId
         &&  this.ZoneGroupId    )
     {
         locWHSZoneGroup = WHSZoneGroup::find(this.ZoneGroupId);
     }
     if(     locWHSZoneGroup.RecId 
         &&  locWHSZoneGroup.AVAWHSZoneGroupShipment)
     {
         retVal = true;
     }
     return retVal;
}
